use tabdat_stats::{
  f_distribution_survival_probability, matrix::lgamma, normal_cdf, student_t_pvalue,
  student_t_quantile,
};

#[test]
fn gamma_and_inference_match_base_r() {
  // Generated by fixtures/gamma_inference_reference.R with R 4.6.1.
  // Relative tail errors matter even far below a generic absolute tolerance.
  // Log-gamma instead needs an absolute budget near its zeros and a relative
  // budget at large arguments, where subtraction loses absolute precision.
  let mut checked = 0;
  for line in include_str!("fixtures/gamma_inference_reference.csv")
    .lines()
    .skip(1)
  {
    let cells: Vec<_> = line.split(',').collect();
    let x: f64 = cells[1].parse().unwrap();
    let df1: f64 = cells[2].parse().unwrap();
    let df2: f64 = cells[3].parse().unwrap();
    let expected: f64 = cells[4].parse().unwrap();
    let actual = match cells[0] {
      "lgamma" => lgamma(x),
      "t_tail" => student_t_pvalue(x, df1),
      "t_quantile" => student_t_quantile(x, df1),
      "f_tail" => f_distribution_survival_probability(x, df1, df2),
      "normal" => normal_cdf(x),
      kind => panic!("unknown reference kind: {kind}"),
    };
    let tolerance = if cells[0] == "lgamma" {
      4e-14 * expected.abs().max(1.0)
    } else if cells[0] == "t_quantile" {
      // R qt(.5, .5) returns about 2.6e-16; symmetry gives exactly zero.
      2e-12 * expected.abs().max(1.0)
    } else {
      2e-12 * expected.abs()
    };
    assert!(
      actual.is_finite() && (actual - expected).abs() <= tolerance,
      "{line}: actual={actual:.17e}, error={:.4e}, tolerance={tolerance:.4e}",
      (actual - expected).abs()
    );
    checked += 1;
  }
  assert_eq!(checked, 153);
}

#[test]
fn invalid_inference_arguments_remain_unavailable() {
  assert!(student_t_pvalue(1.0, 0.0).is_nan());
  assert!(student_t_quantile(1.1, 3.0).is_nan());
  assert!(f_distribution_survival_probability(1.0, 0.0, 3.0).is_nan());
  assert!(normal_cdf(f64::NAN).is_nan());
}
